  async function ensureProfile(){if(!client||!user)return;const username=(user.user_metadata?.username||user.email?.split('@')[0]||'member').toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,30)||'member';const {data,error}=await client.from('profiles').select('*').eq('id',user.id).maybeSingle();if(error)throw error;if(!data){const r=await client.from('profiles').insert({id:user.id,username,display_name:user.user_metadata?.display_name||username});if(r.error)throw r.error;currentProfile=r.data||null}else{currentProfile=data;if(data.avatar_path){const ar=await client.storage.from(MEDIA_BUCKET).createSignedUrl(data.avatar_path,3600);if(!ar.error)currentProfile={...data,avatar_url:ar.data.signedUrl}}}}
