  async function doReactivate(){const r=await client.rpc('mindrid_reactivate_account');if(r.error)throw r.error;await ensureProfile();render();toast('Account reactivated.')}
  function init(){try{if(!window.supabase){app.innerHTML='<div class=\"error\"><strong>mindRID is loading.</strong><br>Please refresh this page.</div>';return}client=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);client.auth.getSession().then(async({data,error})=>{if(error)throw error;user=data.session?.user||null;if(user){try{await ensureProfile();await savePendingIdentity()}catch(e){console.warn('Profile setup:',e)}}if(user&&currentProfile?.is_deactivated){deactivatedScreen()}else render()}).catch(e=>{app.innerHTML=`<div class=\"error\"><strong>mindRID could not connect.</strong><br>${esc(e?.message||'Please refresh and try again.')}</div>`});client.auth.onAuthStateChange(async(_e,s)=>{user=s?.user||null;if(user){try{await ensureProfile();await savePendingIdentity()}catch(e){console.warn('Profile setup:',e)}}if(user&&currentProfile?.is_deactivated){deactivatedScreen()}else render()})}catch(e){app.innerHTML=`<div class=\"error\"><strong>mindRID could not start.</strong><br>${esc(e?.message||'Please refresh and try again.')}</div>`}}
  async function listMine(){if(!client||!user)return guest();const{data,error}=await client.from('whispers').select('*').eq('author_id',user.id).order('created_at',{ascending:false});if(error)throw error;return decorateAuthors(data||[])}
  async function listPublic(){if(!client)return guest().filter(x=>x.visibility==='public');const{data,error}=await client.from('whispers').select('*').eq('visibility','public').order('created_at',{ascending:false}).limit(30);if(error)throw error;return decorateAuthors(data||[])}
  async function getWhisper(id){if(!client)return guest().find(x=>x.id===id)||null;const{data,error}=await client.from('whispers').select('*').eq('id',id).maybeSingle();if(error)throw error;if(!data)return null;return (await decorateAuthors([data]))[0]||data}
  async function decorateAuthors(xs){if(!client||!xs?.length)return xs;const ids=[...new Set(xs.map(x=>x.author_id).filter(Boolean))];if(!ids.length)return xs;const r=await client.from('profiles').select('id,username,display_name,avatar_path').in('id',ids).eq('is_deactivated',false);if(r.error)return xs;const m=new Map((r.data||[]).map(p=>[p.id,p]));return xs.map(x=>({...x,author_profile:m.get(x.author_id)||null}))}
  async function removeUploadedMedia(media){if(!client||!media?.length)return;const paths=media.map(m=>m.storage_path).filter(Boolean);if(paths.length)await client.storage.from(MEDIA_BUCKET).remove(paths).catch(()=>{})}
  async function createWhisper(body,identity,visibility,recipients,media){if(!client||!user)throw new Error('Sign in to post a Whisper.');const{data,error}=await client.from('whispers').insert({author_id:user.id,body,identity_mode:identity,visibility}).select().single();if(error)throw error;try{if(visibility==='selected'&&recipients?.length){const rr=await client.from('whisper_recipients').insert(recipients.map(id=>({whisper_id:data.id,recipient_id:id})));if(rr.error)throw rr.error}if(media?.length){const mr=await client.from('whisper_media').insert(media.map(m=>({...m,whisper_id:data.id,author_id:user.id})));if(mr.error)throw mr.error}return data}catch(e){await client.from('whispers').delete().eq('id',data.id);await removeUploadedMedia(media);throw e}}
  async function updateWhisper(id,body,identity,visibility,recipients,media){const{data,error}=await client.from('whispers').update({body,identity_mode:identity,visibility,updated_at:new Date().toISOString()}).eq('id',id).select().single();if(error)throw error;const oldRecipients=await client.from('whisper_recipients').select('recipient_id').eq('whisper_id',id);if(oldRecipients.error)throw oldRecipients.error;const oldMedia=await client.from('whisper_media').select('storage_path').eq('whisper_id',id);if(oldMedia.error)throw oldMedia.error;const dr=await client.from('whisper_recipients').delete().eq('whisper_id',id);if(dr.error)throw dr.error;try{if(visibility==='selected'&&recipients?.length){const rr=await client.from('whisper_recipients').insert(recipients.map(recipient_id=>({whisper_id:id,recipient_id})));if(rr.error)throw rr.error}if(media?.length){const mr=await client.from('whisper_media').insert(media.map(m=>({...m,whisper_id:id,author_id:user.id})));if(mr.error)throw mr.error}return data}catch(e){await client.from('whisper_recipients').delete().eq('whisper_id',id);if(oldRecipients.data?.length)await client.from('whisper_recipients').insert(oldRecipients.data.map(x=>({whisper_id:id,recipient_id:x.recipient_id})));await removeUploadedMedia(media);throw e}}
  async function deleteWhisper(id){if(!client||!user)throw new Error('Sign in to manage this Whisper.');const mr=await client.from('whisper_media').select('storage_path').eq('whisper_id',id);if(mr.error)throw mr.error;const{error}=await client.from('whispers').delete().eq('id',id);if(error)throw error;await removeUploadedMedia(mr.data||[])}
  async function listMedia(type,id){if(!client||!id)return[];const{data,error}=await client.from(type==='comment'?'comment_media':'whisper_media').select('*').eq(type==='comment'?'comment_id':'whisper_id',id).order('created_at',{ascending:true});if(error)throw error;return await signMedia(data||[])}
  async function signMedia(media){if(!client||!media?.length)return media||[];return await Promise.all(media.map(async m=>{const r=await client.storage.from(MEDIA_BUCKET).createSignedUrl(m.storage_path,3600);return r.error?m:{...m,public_url:r.data.signedUrl}}))}
  async function uploadMedia(file,ownerType){if(!client||!user)throw new Error('Sign in to attach media.');if(!file)return null;const max=50*1024*1024;if(file.size>max)throw new Error('Media must be 50 MB or smaller.');const allowed=['image/','video/','audio/'];if(!allowed.some(x=>file.type.startsWith(x)))throw new Error('Please choose an image, video, or audio file.');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`${user.id}/${crypto.randomUUID()}-${safe}`;const up=await client.storage.from(MEDIA_BUCKET).upload(path,file,{contentType:file.type,upsert:false});if(up.error)throw up.error;return {storage_path:path,public_url:'',mime_type:file.type,file_name:file.name,file_size:file.size,author_id:user.id};}
  async function listComments(id){if(!client)throw new Error('Replies are unavailable while the database is offline.');const{data,error}=await client.from('comments').select('id,whisper_id,body,parent_comment_id,created_at,updated_at,author_id').eq('whisper_id',id).order('created_at',{ascending:true}).limit(150);if(error)throw error;const comments=data||[];const ids=[...new Set(comments.map(c=>c.author_id).filter(Boolean))];if(!ids.length)return comments;if(!client)return comments;const pr=await client.from('profiles').select('id,username,display_name').in('id',ids);if(pr.error)throw pr.error;const byId=new Map((pr.data||[]).map(p=>[p.id,p]));return comments.map(c=>({...c,profiles:byId.get(c.author_id)||null}))}
  async function loadCommentReactions(ids){if(!client||!ids.length)return[];const r=await client.from('comment_reactions').select('comment_id,user_id,reaction').in('comment_id',ids);if(r.error)throw r.error;return r.data||[]}
  async function toggleCommentReaction(commentId,reaction,button){
    if(!client||!user){openAuth('signin');return}
    if(button.disabled)return
    await runAction(button,reaction==='like'?'Reacting…':'Updating…','Reaction updated.',async()=>{
      const q=await client.from('comment_reactions').select('reaction').eq('comment_id',commentId).eq('user_id',user.id).maybeSingle();
      if(q.error)throw q.error;
      const existing=q.data?.reaction;
      if(existing===reaction){
        const d=await client.from('comment_reactions').delete().eq('comment_id',commentId).eq('user_id',user.id);
        if(d.error)throw d.error;
      }else{
        const r=await client.from('comment_reactions').upsert({comment_id:commentId,user_id:user.id,reaction},{onConflict:'comment_id,user_id'});
        if(r.error)throw r.error;
      }
      const box=document.getElementById('comment-'+commentId);
      if(!box)return;
      const thisBtn=box.querySelector('[data-action="comment-reaction"][data-reaction="'+reaction+'"]');
      const other=existing&&existing!==reaction?box.querySelector('[data-action="comment-reaction"][data-reaction="'+existing+'"]'):null;
      if(existing===reaction)thisBtn?.classList.remove('active');
      else{thisBtn?.classList.add('active');other?.classList.remove('active');}
      const countEl=box.querySelector('.comment-reaction-count[data-reaction="'+reaction+'"]');
      if(countEl){let n=parseInt(countEl.textContent||'0',10)||0;n+=existing===reaction?-1:1;countEl.textContent=String(Math.max(0,n));}
      if(existing&&existing!==reaction){
        const otherCount=box.querySelector('.comment-reaction-count[data-reaction="'+existing+'"]');
        if(otherCount){let n=parseInt(otherCount.textContent||'0',10)||0;otherCount.textContent=String(Math.max(0,n-1));}
      }
    });
  }
