  async function submitReport(targetType,id,reason){if(!client||!user)throw new Error('Sign in to report content.');const payload={reporter_id:user.id,reason:reason.trim().slice(0,1000)};payload[targetType==='comment'?'comment_id':'whisper_id']=id;const{error}=await client.from('reports').insert(payload);if(error)throw error;toast('Report received. It is for possible rule violations, not simply disagreement.')}
  function reportDialog(targetType,id){if(!user){openAuth('signin');return}const label=targetType==='comment'?'reply':'Whisper';modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');modal.innerHTML=`<div class="modal-card"><div class="modal-title"><h2>Report ${label}</h2><button class="btn ghost" data-action="close">Close</button></div><p class="hint">Use Report for content that may violate mindRID rules. It is not a dislike button.</p><form id="reportForm"><div class="field"><label for="reportReason">Reason</label><select id="reportReason" class="select" style="width:100%"><option>Harassment or bullying</option><option>Threats or violence</option><option>Hate or abusive content</option><option>Spam, scam or manipulation</option><option>Privacy or personal information</option><option>Sexual or exploitative content</option><option>Illegal or dangerous content</option><option>Other</option></select></div><div class="field"><label for="reportDetails">Additional details (optional)</label><textarea id="reportDetails" maxlength="1000" placeholder="Tell us what needs attention."></textarea></div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close">Cancel</button><button class="btn">Submit report</button></div></form></div>`;const form=document.getElementById('reportForm');form.dataset.targetType=targetType;form.dataset.targetId=id}
  async function toggleLike(id,button){if(!client||!user){openAuth('signin');return}if(button.disabled)return;const {data:existing}=await client.from('likes').select('user_id').eq('whisper_id',id).eq('user_id',user.id).maybeSingle();const liked=!!existing;button.setAttribute('aria-busy','true');try{if(liked){const r=await client.from('likes').delete().eq('whisper_id',id).eq('user_id',user.id);if(r.error)throw r.error;button.classList.remove('active');button.textContent='♡ Like'}else{const r=await client.from('likes').insert({whisper_id:id,user_id:user.id});if(r.error)throw r.error;button.classList.add('active');button.textContent='♥ Liked'}toast(liked?'Like removed.':'Liked.')}finally{button.removeAttribute('aria-busy')}}
  async function toggleSave(id,button){if(!client||!user){openAuth('signin');return}if(button.disabled)return;const {data:existing}=await client.from('saves').select('user_id').eq('whisper_id',id).eq('user_id',user.id).maybeSingle();const saved=!!existing;button.setAttribute('aria-busy','true');try{if(saved){const r=await client.from('saves').delete().eq('whisper_id',id).eq('user_id',user.id);if(r.error)throw r.error;button.classList.remove('active');button.textContent='☆ Save';toast('Removed from Saved.')}else{const r=await client.from('saves').insert({whisper_id:id,user_id:user.id});if(r.error)throw r.error;button.classList.add('active');button.textContent='★ Saved';toast('Saved.')}}finally{button.removeAttribute('aria-busy')}}
  async function share(id,commentId=null){const w=await getWhisper(id);if(!w){toast('This Whisper is unavailable.','error');return}const url=`${location.origin}${location.pathname}#whisper/${encodeURIComponent(id)}${commentId?'?comment='+encodeURIComponent(commentId):''}`;const author=w.identity_mode==='anonymous'?'Anonymous':w.author_id===user?.id?profileName():(w.author_profile?.display_name||w.author_profile?.username||'Someone');const text=commentId?'A reply on mindRID':'Thought shared on mindRID';toast('Preparing share…');try{if(typeof navigator.share==='function'){await navigator.share({title:'mindRID',text,url});toast('Share completed.');return}}catch(e){if(e?.name==='AbortError'){toast('Share cancelled.');return}}try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('Link copied.')}else{const ta=document.createElement('textarea');ta.value=url;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();const ok=document.execCommand('copy');ta.remove();if(!ok)throw new Error('Copy is not available.');toast('Link copied.')}}catch(e){toast('Share link: '+url,'error')}}
  function mediaPreview(media,mode='display'){if(!media?.length)return'';return `<div class="media-grid">${media.map(m=>{const src=esc(m.public_url);const meta=`data-src="${src}" data-mime="${esc(m.mime_type||'')}" data-name="${esc(m.file_name||'Attachment')}"`;if(m.mime_type?.startsWith('image/'))return `<button type="button" class="media-tile media-image" data-action="media-open" ${meta} onclick="event.stopPropagation()"><img src="${src}" alt="Attached media" loading="lazy"><span>Expand</span></button>`;if(m.mime_type?.startsWith('video/'))return `<div class="media-tile media-video"><video controls preload="metadata" src="${src}"></video><button type="button" class="media-expand" data-action="media-open" ${meta}>Expand</button></div>`;if(m.mime_type?.startsWith('audio/'))return `<div class="media-tile"><audio controls src="${src}"></audio><button type="button" class="media-expand" data-action="media-open" ${meta}>Open</button></div>`;return `<a class="media-file" href="${src}" target="_blank" rel="noopener">${esc(m.file_name||'Open attachment')}</a>`}).join('')}</div>`}
  function attachmentPicker(prefix){return `<div class="attachment-row"><label class="attach-btn"><input id="${prefix}Media" type="file" accept="image/*,video/*,audio/*" multiple hidden>＋ Media</label><span id="${prefix}MediaStatus" class="hint">Images, video or audio · max 50 MB each</span></div><div id="${prefix}MediaPreview"></div>`}
  async function prepareFiles(input,prefix){const status=document.getElementById(prefix+'MediaStatus'),preview=document.getElementById(prefix+'MediaPreview');const files=[...(input?.files||[])];if(!files.length)return[];if(!client||!user)throw new Error('Sign in to attach media.');const out=[];try{if(status)status.textContent=`Uploading ${files.length} media item${files.length===1?'':'s'}…`;for(let i=0;i<files.length;i++){if(status)status.textContent=`Uploading ${i+1} of ${files.length}…`;const m=await uploadMedia(files[i]);out.push(m)}if(preview)preview.innerHTML=mediaPreview(out);if(status)status.textContent=`${out.length} media item${out.length===1?'':'s'} attached.`;return out}catch(e){await removeUploadedMedia(out);if(status)status.textContent='Media upload failed. Nothing was posted.';throw e}}
  function composer(){return `<section class="composer"><div class="composer-top"><div class="avatar">${avatarMarkup(currentProfile,profileName())}</div><div style="flex:1"><textarea id="whisperText" maxlength="10000" placeholder="What's on your mind?"></textarea>${attachmentPicker('whisper')}<div class="tag-editor"><input id="tagLocation" placeholder="📍 Location"><input id="tagFeeling" placeholder="❤️ Feeling"><input id="tagIdea" placeholder="💡 Idea"><input id="tagVibe" placeholder="✨ Vibe"></div><div class="composer-bottom"><div class="composer-controls"><select id="identity" class="select" aria-label="Post identity"><option value="anonymous">Anonymous</option><option value="real">Me</option></select><select id="visibility" class="select" aria-label="Post visibility"><option value="public">Public</option><option value="selected">People I choose</option><option value="private">Private</option></select></div><button class="btn" data-action="save">WHISPER</button></div><div class="hint" style="margin-top:8px">Tag the context of a thought so mindRID can connect related ideas, feelings and experiences.</div><div id="recipientBox" class="recipient-box hidden"><label>Recipients</label><input id="recipientNames" placeholder="Usernames, separated by commas"><div class="hint">Selected people will be able to see this Whisper.</div></div></div></div></section>`}
  async function resolveRecipients(){const box=document.getElementById('recipientBox');if(!box||box.classList.contains('hidden'))return[];const names=(document.getElementById('recipientNames')?.value||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);if(!names.length)throw new Error('Choose at least one recipient for a selected Whisper.');const{data,error}=await client.from('profiles').select('id,username').in('username',names);if(error)throw error;const found=(data||[]);const missing=names.filter(n=>!found.some(x=>x.username===n));if(missing.length)throw new Error(`Could not find: ${missing.join(', ')}`);return found.map(x=>x.id)}
  function card(w,media=[]){const anonymous=w.identity_mode!=='real';const name=anonymous?'Anonymous':(w.author_id===user?.id?profileName():(w.author_profile?.display_name||w.author_profile?.username||'Someone'));const mine=w.author_id===user?.id;return `<article class="whisper" data-action="open" data-id="${esc(w.id)}"><div class="avatar">${anonymous?'A':esc((name[0]||'S').toUpperCase())}</div><div class="whisper-main"><div class="whisper-meta"><span class="name">${esc(name)}</span><span class="time">· ${fmt(w.created_at)}${w.updated_at&&w.updated_at!==w.created_at?' · edited':''}</span></div><div class="whisper-body">${esc(w.body)}</div><div class="tag-row" id="tags-${esc(w.id)}"></div><div class="media-slot" id="media-${esc(w.id)}">${mediaPreview(media)}</div><div class="whisper-actions"><button class="action" data-action="like" data-id="${esc(w.id)}" onclick="event.stopPropagation()">♡ Like</button><button class="action" data-action="open" data-id="${esc(w.id)}" onclick="event.stopPropagation()">💬 Reply</button><button class="action" data-action="save-toggle" data-id="${esc(w.id)}" onclick="event.stopPropagation()">☆ Save</button><button class="action" data-action="share" data-id="${esc(w.id)}" onclick="event.stopPropagation()">↗ Share</button>${mine?`<button class="action" data-action="edit" data-id="${esc(w.id)}" onclick="event.stopPropagation()">Edit</button><button class="action danger-text" data-action="delete" data-id="${esc(w.id)}" onclick="event.stopPropagation()">Delete</button>`:`<button class="action" data-action="report" data-id="${esc(w.id)}" title="Report possible rule violations, not disagreement" onclick="event.stopPropagation()">Report</button>`}</div></div></article>`}
  function loadCards(xs){return xs.map(w=>card(w,[])).join('')}
  async function hydrateFeedMedia(xs){if(!client||!xs.length)return;const ids=xs.map(x=>x.id);const [r,tr]=await Promise.all([client.from('whisper_media').select('*').in('whisper_id',ids).order('created_at',{ascending:true}),client.from('whisper_tags').select('*').in('whisper_id',ids)]);if(!r.error){const media=await signMedia(r.data||[]);const by=new Map();media.forEach(m=>{if(!by.has(m.whisper_id))by.set(m.whisper_id,[]);by.get(m.whisper_id).push(m)});xs.forEach(w=>{const slot=document.getElementById('media-'+w.id);if(slot)slot.innerHTML=mediaPreview(by.get(w.id)||[])})}if(!tr.error){const tb=new Map();(tr.data||[]).forEach(t=>{if(!tb.has(t.whisper_id))tb.set(t.whisper_id,[]);tb.get(t.whisper_id).push(t)});xs.forEach(w=>{const el=document.getElementById('tags-'+w.id);if(el)el.innerHTML=tagHTML(tb.get(w.id)||[])})}}
  async function home(){app.innerHTML=shell('Home','Thoughts from people on mindRID')+composer()+`<div id="feed" class="feed"><div class="empty">Loading…</div></div>`;bindComposer();try{const xs=await listPublic();document.getElementById('feed').innerHTML=xs.length?loadCards(xs):`<div class="empty">Nothing public yet. Be the first to Whisper.</div>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{} )}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}}
  async function searchWhispers(q){if(!client||!q)return[];const term=q.trim();if(!term)return[];const r=await client.from('whispers').select('*').eq('visibility','public').ilike('body',`%${term}%`).order('created_at',{ascending:false}).limit(30);if(r.error)throw r.error;return decorateAuthors(r.data||[])}
  async function explore(mode='latest',query=''){app.innerHTML=shell('Explore','Discover public thoughts, media and common ground')+`<div class="tabs"><a class="${mode==='latest'?'active':''}" href="#explore">Latest</a><a class="${mode==='read'?'active':''}" href="#explore/read">Read</a><a class="${mode==='listen'?'active':''}" href="#explore/listen">Listen</a><a class="${mode==='see'?'active':''}" href="#explore/see">See</a><a class="${mode==='common'?'active':''}" href="#explore/common">Common</a></div><div id="feed" class="feed"><div class="empty">Loading…</div></div>`;try{let xs=query?await searchWhispers(query):await listPublic();if(mode==='listen'||mode==='see'){const ids=xs.map(x=>x.id);const mr=ids.length?await client.from('whisper_media').select('whisper_id,mime_type').in('whisper_id',ids):{data:[],error:null};if(!mr.error){const kinds=new Map();(mr.data||[]).forEach(m=>{if(!kinds.has(m.whisper_id))kinds.set(m.whisper_id,[]);kinds.get(m.whisper_id).push(m.mime_type)});xs=xs.filter(w=>(kinds.get(w.id)||[]).some(t=>mode==='listen'?t?.startsWith('audio/'):t?.startsWith('image/')||t?.startsWith('video/')))}}if(mode==='common'&&user){const tags=await client.from('whisper_tags').select('whisper_id,tag_type,tag_value').limit(500);const common=new Set((currentProfile?.interests||[]).map(x=>x.toLowerCase()));if(!tags.error)xs=xs.filter(w=>(tags.data||[]).some(t=>t.whisper_id===w.id&&common.has(String(t.tag_value).toLowerCase())))}document.getElementById('feed').innerHTML=xs.length?loadCards(xs):`<div class="empty">No matching Whispers yet.</div>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{})}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}}
  async function saved(){
    if(!user){app.innerHTML=shell('Saved')+`<div class="auth-box"><h1>Your Saved Whispers</h1><p>Sign in to keep saved thoughts across devices.</p><button class="btn" data-action="auth">Sign in / Create account</button></div>`;return}
    app.innerHTML=shell('Saved','Whispers you chose to keep')+`<div id="feed" class="feed"><div class="empty">Loading…</div></div>`;
    try{const r=await client.from('saves').select('whisper_id,created_at').eq('user_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;const ids=(r.data||[]).map(x=>x.whisper_id);let xs=[];if(ids.length){const w=await client.from('whispers').select('*').in('id',ids);if(w.error)throw w.error;const byId=new Map((w.data||[]).map(x=>[x.id,x]));xs=ids.map(id=>byId.get(id)).filter(Boolean)}document.getElementById('feed').innerHTML=xs.length?loadCards(xs):`<div class="empty">Nothing saved yet.</div>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{} )}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}
  }
  async function my(){if(!user){app.innerHTML=shell('My Whispers')+`<div class="auth-box"><h1>Your Whispers</h1><p>Sign in to keep your thoughts across devices and join conversations.</p><button class="btn" data-action="auth">Sign in / Create account</button></div>`;return}app.innerHTML=shell('My Whispers','Everything you have left here')+`<div id="feed" class="feed"><div class="empty">Loading…</div></div>`;try{const xs=await listMine();document.getElementById('feed').innerHTML=xs.length?loadCards(xs):`<div class="empty">You haven't left a Whisper yet.</div>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{} )}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}}
  async function openWhisper(id){let w=null;try{w=await getWhisper(id);if(user&&!w){const mine=await listMine();w=mine.find(x=>x.id===id)}}catch(e){}if(!w){toast('That Whisper is unavailable.','error');return}currentWhisper=w;app.innerHTML=`<div class="page-head"><a href="#${w.author_id===user?.id?'my':'home'}" style="color:var(--accent);text-decoration:none">← Back</a></div><article class="thread"><div class="whisper-meta"><span class="name">${w.identity_mode==='real'?esc(w.author_id===user?.id?profileName():(w.author_profile?.display_name||w.author_profile?.username||'Someone')):'Anonymous'}</span><span class="time">· ${fmt(w.created_at)}${w.updated_at!==w.created_at?' · edited':''}</span></div><div class="thread-body">${esc(w.body)}</div><div id="threadTags"><div class="empty">Loading tags…</div></div><div id="threadMedia"><div class="empty">Loading media…</div></div><div class="thread-actions"><button class="action" data-action="like" data-id="${esc(w.id)}">♡ Like</button><button class="action" data-action="save-toggle" data-id="${esc(w.id)}">☆ Save</button><button class="action" data-action="share" data-id="${esc(w.id)}">↗ Share</button>${w.author_id===user?.id?`<button class="action" data-action="edit" data-id="${esc(w.id)}">Edit</button><button class="action danger-text" data-action="delete" data-id="${esc(w.id)}">Delete</button>`:`<button class="action" data-action="report" data-id="${esc(w.id)}" title="Report possible rule violations, not disagreement">Report</button>`}</div></article><section class="comments"><h3>Replies</h3><div id="commentArea"><div class="empty">Loading replies…</div></div></section>`;const mediaPromise=listMedia('whisper',id).catch(()=>[]);const commentsPromise=(client&&w.visibility!=='private')?renderComments(w.id):Promise.resolve();const media=await mediaPromise;const slot=document.getElementById('threadMedia');if(slot)slot.innerHTML=mediaPreview(media);const tg=await client.from('whisper_tags').select('*').eq('whisper_id',id);const tagSlot=document.getElementById('threadTags');if(tagSlot)tagSlot.innerHTML=tagHTML(tg.error?[]:(tg.data||[]));await commentsPromise;const match=(location.hash.split('?')[1]||'').match(/(?:^|&)comment=([^&]+)/);if(match){setTimeout(()=>document.getElementById('comment-'+decodeURIComponent(match[1]))?.scrollIntoView({behavior:'smooth',block:'center'}),60)}}
  function commentHTML(c,all,media=[],reactionMap=new Map()){const name=c.profiles?.display_name||c.profiles?.username||'Someone';const kids=all.filter(x=>x.parent_comment_id===c.id);const mine=c.author_id===user?.id;const r=reactionMap.get(c.id)||{like:0,dislike:0,mine:null};return `<div class="comment ${c.parent_comment_id?'reply':''}" id="comment-${esc(c.id)}"><div class="comment-meta"><span class="comment-author">${esc(name)}</span> · ${fmt(c.created_at)}${c.updated_at!==c.created_at?' · edited':''}</div><div class="comment-body">${esc(c.body)}</div>${mediaPreview(media.filter(m=>m.comment_id===c.id))}<div class="comment-actions">${user?`<button class="action ${r.mine==='like'?'active':''}" data-action="comment-reaction" data-reaction="like" data-comment="${esc(c.id)}">♥ <span class="comment-reaction-count" data-reaction="like">${r.like}</span></button><button class="action ${r.mine==='dislike'?'active':''}" data-action="comment-reaction" data-reaction="dislike" data-comment="${esc(c.id)}">👎 <span class="comment-reaction-count" data-reaction="dislike">${r.dislike}</span></button><button class="action" data-action="reply-comment" data-comment="${esc(c.id)}">↩ Reply</button>`:''}<button class="action" data-action="share-comment" data-whisper="${esc(c.whisper_id)}" data-comment="${esc(c.id)}">↗ Share</button>${mine?`<button class="action" data-action="edit-comment" data-comment="${esc(c.id)}">Edit</button><button class="action danger-text" data-action="delete-comment" data-comment="${esc(c.id)}">Delete</button>`:user?`<button class="action" title="Report possible rule violations, not disagreement" data-action="report-comment" data-comment="${esc(c.id)}">Report</button>`:''}</div>${kids.map(x=>commentHTML(x,all,media,reactionMap)).join('')}</div>`}
  async function renderComments(id){const el=document.getElementById('commentArea');try{const cs=await listComments(id);let media=[];let reactions=[];if(client&&cs.length){const [mr,rr]=await Promise.all([client.from('comment_media').select('*').in('comment_id',cs.map(c=>c.id)),loadCommentReactions(cs.map(c=>c.id))]);if(!mr.error)media=await signMedia(mr.data||[]);reactions=rr}const reactionMap=new Map();reactions.forEach(x=>{const r=reactionMap.get(x.comment_id)||{like:0,dislike:0,mine:null};r[x.reaction]=(r[x.reaction]||0)+1;if(x.user_id===user?.id)r.mine=x.reaction;reactionMap.set(x.comment_id,r)});el.innerHTML=(user?`<form class="reply-form" id="replyForm"><input id="replyInput" maxlength="3000" placeholder="Write a reply…"><button class="btn">Reply</button></form>${attachmentPicker('reply')}`:'<div class="notice">Sign in to reply.</div>')+(cs.length?cs.map(c=>!c.parent_comment_id?commentHTML(c,cs,media,reactionMap):'').join(''):'<div class="empty">No replies yet. Be the first to add one.</div>');}catch(e){el.innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry-comments">Try again</button></div>`}}
    function tagHTML(tags){if(!tags?.length)return'';return `<div class="tag-row">${tags.map(t=>`<span class="tag-pill">${esc(t.tag_type)}: ${esc(t.tag_value)}</span>`).join('')}</div>`}
  function collectTags(){return [['location','tagLocation'],['feeling','tagFeeling'],['idea','tagIdea'],['vibe','tagVibe']].map(([type,id])=>({tag_type:type,tag_value:(document.getElementById(id)?.value||'').trim()})).filter(x=>x.tag_value)}
