  async function searchProfiles(q){if(!client||!q.trim())return[];const x=q.trim().replace(/[%_]/g,'');const r=await client.from('profiles').select('id,username,display_name,avatar_path,location_city,location_country,interests').or(`username.ilike.%${x}%,display_name.ilike.%${x}%`).neq('id',user?.id||'00000000-0000-0000-0000-000000000000').eq('is_deactivated',false).limit(8);if(r.error)throw r.error;return r.data||[]}
