  async function people(){if(!user){app.innerHTML=shell('People','Discover people through thoughts and common ground')+`<div class="auth-box"><p>Sign in to discover people, connections and shared interests.</p><button class="btn" data-action="auth">Sign in / Create account</button></div>`;return}app.innerHTML=shell('People','Discover people through thoughts, interests and common ground')+`<div class="discovery-tabs"><button class="btn ghost" data-action="people-refresh">People you may connect with</button><a class="btn ghost" href="#groups">Groups</a></div><div id="peopleList" class="people-list"><div class="empty">Finding people…</div></div>`;try{const r=await client.from('profiles').select('id,username,display_name,bio,location_city,location_country,background,interests,avatar_path').neq('id',user.id).eq('is_deactivated',false).limit(60);if(r.error)throw r.error;const rows=r.data||[];const me=currentProfile||{};const con=await client.from('connections').select('*').or(`requester_id.eq.${user.id},addressee_id.eq.${user.id}`);const conRows=con.data||[];const connected=new Map();conRows.forEach(c=>connected.set(c.requester_id===user.id?c.addressee_id:c.requester_id,c));rows.sort((a,b)=>{const score=p=>((p.location_city&&me.location_city&&p.location_city.toLowerCase()===me.location_city.toLowerCase())?3:0)+((p.interests||[]).filter(x=>(me.interests||[]).includes(x)).length);return score(b)-score(a)});document.getElementById('peopleList').innerHTML=rows.slice(0,30).map(p=>{const c=connected.get(p.id);const common=(p.interests||[]).filter(x=>(me.interests||[]).includes(x));return `<article class="person-card"><div class="avatar">${esc((p.display_name||p.username||'P')[0].toUpperCase())}</div><div class="person-main"><strong>${esc(p.display_name||p.username)}</strong><div class="hint">@${esc(p.username)}${p.location_city?` · ${esc(p.location_city)}`:''}</div>${p.bio?`<p>${esc(p.bio)}</p>`:''}<div class="common-row">${p.location_city&&me.location_city&&p.location_city===me.location_city?'<span class="tag-pill">Same city</span>':''}${common.slice(0,3).map(x=>`<span class="tag-pill">Common: ${esc(x)}</span>`).join('')}</div></div><div>${!c?`<button class="btn" data-action="connect" data-user-id="${esc(p.id)}">Connect</button>`:c.status==='accepted'?`<button class="btn ghost" data-action="disconnect" data-user-id="${esc(p.id)}">Disconnect</button>`:c.requester_id===user.id?`<button class="btn ghost" data-action="disconnect" data-user-id="${esc(p.id)}">Pending</button>`:`<button class="btn" data-action="accept-connection" data-user-id="${esc(p.id)}">Accept</button>`}</div></article>`}).join('')||`<div class="empty">No people found yet.</div>`}catch(e){document.getElementById('peopleList').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
